import type { ComputedRef, Ref } from 'vue';
import type { ReplaceNamesData } from '../ReplaceNamesModal.vue';
import type { RawData, SelectedGridItem } from '../types';
import { persistRawData } from '../utils/persist';

interface SelectionApi {
  clear: () => void;
  isSelected: (item: { id: string }) => boolean;
  remove: (item: { id: string }) => void;
}

interface SetSelectionApi {
  toggle: (item: unknown, idx: number) => void;
}

interface UseQuickSendHandlersOptions {
  rawData: RawData;
  editMode: Ref<boolean>;
  showPrefixList: Ref<boolean>;
  showSuffixList: Ref<boolean>;
  replaceNamesModalOpen: Ref<boolean>;
  replaceNamesType: Ref<'user' | 'char'>;
  gridCurrent: ComputedRef<{ values: unknown[] }>;
  gridDragList: Ref<string[]>;
  gridPath: Ref<number[]>;
  selectedGridIndex: Ref<number | null>;
  selectedGridItems: Ref<SelectedGridItem[]>;
  gridSelection: SelectionApi;
  prefixSelection: SetSelectionApi;
  suffixSelection: SetSelectionApi;
  text: Ref<string>;
  makeIdForGridIdx: (idx: number) => string;
  syncSelectedGridText: () => void;
  appendSillyTavernText: () => void;
  applyMacroSubstitution: () => void;
  onClose?: () => void;
}

/** 快捷指令面板交互处理器：选中、前后缀、替换词、发送与关闭 */
export function useQuickSendHandlers(options: UseQuickSendHandlersOptions) {
  const handleClose = (): void => { options.onClose?.(); };
  const handleEdit = (): void => { options.editMode.value = !options.editMode.value; };

  /** 判断 Grid 项是否已加入已选列表 */
  function isGridEntrySelected(idx: number): boolean {
    return options.gridSelection.isSelected({ id: options.makeIdForGridIdx(idx) });
  }

  /** 移除指定已选 Grid 项 */
  function removeSelectedGridItem(id: string): void {
    options.gridSelection.remove({ id });
    options.syncSelectedGridText();
  }

  /** 清空已选 Grid 项 */
  function clearSelectedGridItems(): void {
    options.gridSelection.clear();
    options.syncSelectedGridText();
  }

  /** 处理 Grid 点击：叶子节点选中，非叶子节点下钻 */
  function onGridEntryClick(idx: number, config: { replace?: boolean } = {}): void {
    if (options.editMode.value) return;
    options.selectedGridIndex.value = idx;
    const content = nodeContent(options.gridCurrent.value.values[idx]);
    if (content == null) {
      options.gridPath.value = [...options.gridPath.value, idx];
      options.selectedGridIndex.value = 0;
      return;
    }
    selectGridLeaf(options, idx, content, config.replace);
  }

  /** 切换前缀列表展开状态 */
  function togglePrefixList(): void {
    options.showPrefixList.value = !options.showPrefixList.value;
    if (options.showPrefixList.value) options.showSuffixList.value = false;
  }

  /** 切换后缀列表展开状态 */
  function toggleSuffixList(): void {
    options.showSuffixList.value = !options.showSuffixList.value;
    if (options.showSuffixList.value) options.showPrefixList.value = false;
  }

  /** 处理前缀项点击 */
  function onPrefixItemClick(_item: unknown, idx: number): void {
    if (!options.editMode.value) options.prefixSelection.toggle(null, idx);
  }

  /** 处理后缀项点击 */
  function onSuffixItemClick(_item: unknown, idx: number): void {
    if (!options.editMode.value) options.suffixSelection.toggle(null, idx);
  }

  /** 打开替换词编辑弹窗 */
  function openReplaceNamesModal(type: 'user' | 'char'): void {
    options.replaceNamesType.value = type;
    options.replaceNamesModalOpen.value = true;
  }

  /** 保存替换词并重新应用 Macro */
  function handleReplaceNamesSave(result: ReplaceNamesData): void {
    options.rawData.replaceNames = {
      user: Array.isArray(result.user) ? [...result.user] : [],
      char: Array.isArray(result.char) ? [...result.char] : [],
    };
    persistRawData(options.rawData);
    options.applyMacroSubstitution();
  }

  /** 发送当前快捷文本并关闭面板 */
  function sendQuickText(): void {
    triggerSlash(`/send ${options.text.value}|/trigger`);
    options.onClose?.();
  }

  return {
    handleClose,
    handleEdit,
    isGridEntrySelected,
    removeSelectedGridItem,
    clearSelectedGridItems,
    onGridEntryClick,
    togglePrefixList,
    toggleSuffixList,
    onPrefixItemClick,
    onSuffixItemClick,
    openReplaceNamesModal,
    handleReplaceNamesSave,
    sendQuickText,
  };
}

/** 读取 Grid 节点中的可发送文本 */
function nodeContent(node: unknown): string | undefined {
  return typeof node === 'string' ? node : undefined;
}

/** 选中 Grid 叶子节点并同步发送文本 */
function selectGridLeaf(
  options: UseQuickSendHandlersOptions,
  idx: number,
  content: string,
  replace?: boolean,
): void {
  const item = {
    id: options.makeIdForGridIdx(idx),
    label: options.gridDragList.value[idx] ?? String(idx),
    value: content,
  };
  if (replace) {
    options.selectedGridItems.value = [item];
  } else if (options.gridSelection.isSelected({ id: item.id })) {
    options.gridSelection.remove({ id: item.id });
  } else {
    options.selectedGridItems.value = [...options.selectedGridItems.value, item];
  }
  options.syncSelectedGridText();
  options.appendSillyTavernText();
}
