import { computed, ref } from 'vue';
import type { RawData } from '../types';
import { persistRawData } from '../utils/persist';

export interface FixedPrefixSuffixData {
  prefix: string;
  suffix: string;
}

/** 固定前后缀状态管理：负责弹窗数据、打开动作与 rawData 写回 */
export function useFixedPrefixSuffix(rawData: RawData) {
  const fixedPrefix = ref(rawData.fixedPrefixSuffix?.prefix || '');
  const fixedSuffix = ref(rawData.fixedPrefixSuffix?.suffix || '');
  const fixedPrefixSuffixModalOpen = ref(false);
  const fixedPrefixSuffixData = computed<FixedPrefixSuffixData>(() => ({
    prefix: fixedPrefix.value,
    suffix: fixedSuffix.value,
  }));

  /** 打开固定前后缀设置弹窗 */
  function openFixedPrefixSuffixModal(): void {
    fixedPrefixSuffixModalOpen.value = true;
  }

  /** 保存固定前后缀并持久化 */
  function handleFixedPrefixSuffixSave(result: FixedPrefixSuffixData): void {
    fixedPrefix.value = result.prefix;
    fixedSuffix.value = result.suffix;
    rawData.fixedPrefixSuffix = { prefix: result.prefix, suffix: result.suffix };
    persistRawData(rawData);
  }

  return {
    fixedPrefix,
    fixedSuffix,
    fixedPrefixSuffixModalOpen,
    fixedPrefixSuffixData,
    openFixedPrefixSuffixModal,
    handleFixedPrefixSuffixSave,
  };
}
