import _ from 'lodash';
import type { DataPath } from '../types';

// 共享类型来源统一收口至 types.ts，本模块对外保持原 import 路径兼容
export type { DataPath } from '../types';

/**
 * 通用的節點展開結果
 */
export interface ParsedItem<T = unknown> {
  /** 用於顯示的文字 */
  label: string;
  /** 原始值的引用 */
  value: T;
  /** 指向原始資料的位置路徑 */
  path: DataPath;
  /** 是否為字串葉節點 */
  isLeaf: boolean;
  /** 此節點是否允許改名 */
  canRename: boolean;
}

/**
 * 依照 SillyTavern 快捷指令資料的慣例，展開陣列或物件產生扁平化列表。
 *
 * - 陣列元素為字串：直接視為葉子，label=字串。
 * - 陣列元素為單鍵物件：拆出鍵名，label=鍵名，可改名。
 * - 陣列元素為多鍵物件：對每個鍵各自產生一筆資料。
 * - 物件：逐鍵展開。
 *
 * @param node    目前的資料節點
 * @param basePath 節點對應的資料路徑（展開結果會在此基礎上延伸）
 */
export function expandArrayLike(node: any, basePath: DataPath = []): ParsedItem[] {
  if (node == null) return [];

  const results: ParsedItem[] = [];

  if (Array.isArray(node)) {
    node.forEach((element, index) => {
      const elementPath = [...basePath, index] as DataPath;

      if (_.isString(element)) {
        results.push({
          label: element,
          value: element,
          path: elementPath,
          isLeaf: true,
          canRename: false,
        });
        return;
      }

      if (_.isPlainObject(element)) {
        const keys = Object.keys(element as Record<string, unknown>);

        if (keys.length === 1) {
          const key = keys[0];
          const value = (element as any)[key];
          results.push({
            label: key,
            value,
            path: [...elementPath, key] as DataPath,
            isLeaf: _.isString(value),
            canRename: true,
          });
          return;
        }

        if (keys.length > 1) {
          keys.forEach(key => {
            const value = (element as any)[key];
            results.push({
              label: key,
              value,
              path: [...elementPath, key] as DataPath,
              isLeaf: _.isString(value),
              canRename: true,
            });
          });
          return;
        }
      }

      results.push({
        label: _.isString(element) ? element : String(index),
        value: element,
        path: elementPath,
        isLeaf: _.isString(element),
        canRename: false,
      });
    });

    return results;
  }

  if (_.isPlainObject(node)) {
    return Object.keys(node as Record<string, unknown>).map(key => {
      const value = (node as any)[key];
      return {
        label: key,
        value,
        path: [...basePath, key] as DataPath,
        isLeaf: _.isString(value),
        canRename: true,
      };
    });
  }

  return results;
}
