import { ref, watch, type Ref, type ComputedRef } from 'vue';
import type { SelectedGridItem, PrefixSuffixItem } from '../types';
import { escapeForRegExp } from '../utils/util';

interface UseMacroSubstitutionOptions {
  replaceNames: ComputedRef<{ user?: string[]; char?: string[] } | undefined>;
  selectedGridItems: Ref<SelectedGridItem[]>;
  prefixList: ComputedRef<PrefixSuffixItem[]>;
  suffixList: ComputedRef<PrefixSuffixItem[]>;
  selectedPrefixIndexes: Ref<Set<number>>;
  selectedSuffixIndexes: Ref<Set<number>>;
  fixedPrefix: Ref<string>;
  fixedSuffix: Ref<string>;
  userName: () => string;
  charName: () => string;
}

/**
 * Macro 替换 composable
 *
 * 管理文本替换逻辑、替换开关、文本同步
 */
export function useMacroSubstitution(options: UseMacroSubstitutionOptions) {
  const {
    replaceNames,
    selectedGridItems,
    prefixList,
    suffixList,
    selectedPrefixIndexes,
    selectedSuffixIndexes,
    fixedPrefix,
    fixedSuffix,
    userName,
    charName,
  } = options;

  // 从 localStorage 恢复替换开关
  const restoreReplaceNames = () => {
    try {
      const stored = localStorage.getItem('quicksend:lastReplaceNames');
      if (stored) {
        const saved = JSON.parse(stored);
        return {
          user: saved.user ?? false,
          char: saved.char ?? false,
        };
      }
    } catch (e) {
      // ignore
    }
    return { user: false, char: false };
  };

  const lastReplaceNames = restoreReplaceNames();
  const replaceUserNames = ref(lastReplaceNames.user);
  const replaceCharNames = ref(lastReplaceNames.char);

  const text = ref('');
  const originalText = ref('');
  const tavernText = ref('');

  /**
   * 获取前缀/后缀项的值
   */
  function getPrefixSuffixValue(item: any): string {
    if (item && typeof item === 'object' && !Array.isArray(item)) {
      const keys = Object.keys(item);
      if (keys.length > 0) {
        const value = item[keys[0]];
        return typeof value === 'string' ? value : String(value);
      }
    }
    return '';
  }

  /**
   * 应用 Macro 替换到文本
   */
  function applyMacroToText(input: string): string {
    let processed = input;

    // 替换 {{user}}
    if (replaceUserNames.value && userName() && replaceNames.value?.user) {
      const userSet = new Set<string>(replaceNames.value.user as string[]);
      userSet.forEach(raw => {
        if (!raw) return;
        const pattern = escapeForRegExp(raw);
        const reg = new RegExp(pattern, 'gi');
        processed = processed.replace(reg, userName());
      });
    }

    // 替换 {{char}}
    if (replaceCharNames.value && charName() && replaceNames.value?.char) {
      const charSet = new Set<string>(replaceNames.value.char as string[]);
      charSet.forEach(raw => {
        if (!raw) return;
        const pattern = escapeForRegExp(raw);
        const reg = new RegExp(pattern, 'gi');
        processed = processed.replace(reg, charName());
      });
    }

    return processed;
  }

  /**
   * 构建选中的前缀/后缀拼接文本
   */
  function buildSelectedConcat(list: PrefixSuffixItem[], selected: Set<number>): string {
    let out = '';
    list.forEach((item, idx) => {
      if (selected.has(idx)) {
        const v = getPrefixSuffixValue(item);
        if (v) out += v;
      }
    });
    return out;
  }

  /**
   * 应用 Macro 替换到完整文本
   */
  function applyMacroSubstitution() {
    // 对原始文本应用宏替换
    const processedText = applyMacroToText(originalText.value);

    // 构建前后缀
    const prefixConcatRaw = buildSelectedConcat(prefixList.value, selectedPrefixIndexes.value);
    const suffixConcatRaw = buildSelectedConcat(suffixList.value, selectedSuffixIndexes.value);
    const fixedPreRaw = fixedPrefix.value || '';
    const fixedSufRaw = fixedSuffix.value || '';

    // 对前后缀和固定前后缀也应用宏替换
    const fixedPre = applyMacroToText(fixedPreRaw);
    const prefixConcat = applyMacroToText(prefixConcatRaw);
    const suffixConcat = applyMacroToText(suffixConcatRaw);
    const fixedSuf = applyMacroToText(fixedSufRaw);

    // 拼接处理后的文本（固定前后缀需要出现在最外层）
    const mainText = `${fixedPre}${prefixConcat}${processedText}${suffixConcat}${fixedSuf}`;

    // 最后追加酒馆文本（不应用宏替换）
    text.value = tavernText.value ? `${mainText}\n\n${tavernText.value}` : mainText;
  }

  /**
   * 同步选中 Grid 项的文本
   */
  function syncSelectedGridText() {
    originalText.value = selectedGridItems.value.map(item => item.value).join('');
  }

  /**
   * 追加 SillyTavern 文本
   */
  function appendSillyTavernText() {
    try {
      // 快捷指令面板在 iframe 中运行，需要访问父页面的输入框
      const textarea = window.parent.document.querySelector('#send_textarea') as HTMLTextAreaElement;
      if (textarea) {
        tavernText.value = textarea.value;
      }
    } catch (e) {
      // 跨域或其他错误时静默失败
      console.warn('[快捷指令面板] 无法访问 ST 输入框:', e);
    }
    applyMacroSubstitution();
  }

  // watch 自动触发
  watch(
    selectedGridItems,
    () => {
      syncSelectedGridText();
    },
    { deep: true },
  );

  watch(originalText, () => {
    applyMacroSubstitution();
  });

  watch([replaceUserNames, replaceCharNames], () => {
    applyMacroSubstitution();

    // 持久化到 localStorage
    try {
      localStorage.setItem(
        'quicksend:lastReplaceNames',
        JSON.stringify({
          user: replaceUserNames.value,
          char: replaceCharNames.value,
        }),
      );
    } catch (e) {
      // ignore
    }
  });

  watch(
    [selectedPrefixIndexes, selectedSuffixIndexes],
    () => {
      applyMacroSubstitution();
    },
    { deep: true },
  );

  watch([fixedPrefix, fixedSuffix], () => {
    applyMacroSubstitution();
  });

  return {
    replaceUserNames,
    replaceCharNames,
    text,
    originalText,
    tavernText,
    applyMacroSubstitution,
    syncSelectedGridText,
    appendSillyTavernText,
  };
}
