import { ref, computed, watch, type Ref } from 'vue';
import type { ItemEntry, DataPath, PrefixSuffixItem, LastSelection } from '../types';
import { expandArrayLike } from '../utils/data-parser';

interface UseLevelNavigationOptions {
  data: Ref<unknown[]>;
  prefix: Ref<PrefixSuffixItem[]>;
  suffix: Ref<PrefixSuffixItem[]>;
  editMode: Ref<boolean>;
}

/**
 * 层级导航 composable
 *
 * 管理 L1/L2 tab 切换、Grid 下钻路径、面包屑导航
 */
export function useLevelNavigation(options: UseLevelNavigationOptions) {
  const { data, editMode } = options;

  // 内部状态
  const activeTabIndex = ref(0);
  const activeSecondIndex = ref(0);
  const gridPath = ref<number[]>([]);

  // 从 localStorage 恢复
  /** 从 localStorage 恢复上次选择 */
  const restoreFromStorage = (): LastSelection => {
    try {
      const stored = localStorage.getItem('quicksend:lastSelection');
      if (stored) {
        const saved = JSON.parse(stored);
        return {
          l1: saved.l1 ?? 0,
          l2: saved.l2 ?? 0,
          path: Array.isArray(saved.path) ? saved.path : [],
          sel: saved.sel ?? null,
        };
      }
    } catch (e) {
      // ignore
    }
    return { l1: 0, l2: 0, path: [], sel: null };
  };

  // computed
  const level1Entries = computed<ItemEntry[]>(() => {
    const items = expandArrayLike(data.value, []);
    return items.map(item => ({
      label: item.label,
      value: item.value,
      path: item.path,
    }));
  });

  const level1Labels = computed<string[]>(() => level1Entries.value.map(entry => entry.label));

  const level2Entries = computed<ItemEntry[]>(() => {
    const level1Entry = level1Entries.value[activeTabIndex.value];
    if (!level1Entry) return [];
    const items = expandArrayLike(level1Entry.value, level1Entry.path);
    return items.map(item => ({
      label: item.label,
      value: item.value,
      path: item.path,
    }));
  });

  const level2Labels = computed<string[]>(() => level2Entries.value.map(entry => entry.label));

  const gridBaseEntry = computed<ItemEntry | null>(() => level2Entries.value[activeSecondIndex.value] ?? null);

  /**
   * 计算网格条目
   */
  const computeGridEntries = (
    node: unknown,
    basePath: DataPath,
  ): { labels: string[]; values: unknown[]; metas: Array<{ path: DataPath }> } => {
    const items = expandArrayLike(node, basePath);
    return {
      labels: items.map(item => item.label),
      values: items.map(item => item.value),
      metas: items.map(item => ({ path: item.path })),
    };
  };

  const gridCurrent = computed(() => {
    const baseEntry = gridBaseEntry.value;
    if (!baseEntry) return { labels: [], values: [] as unknown[], metas: [] as Array<{ path: DataPath }> };
    let cur: unknown = baseEntry.value;
    let curPath: DataPath = baseEntry.path;
    for (const idx of gridPath.value) {
      const step = computeGridEntries(cur, curPath);
      const meta = step.metas[idx];
      if (!meta) return { labels: [], values: [] as unknown[], metas: [] as Array<{ path: DataPath }> };
      cur = step.values[idx];
      curPath = meta.path;
    }
    return computeGridEntries(cur, curPath);
  });

  /**
   * 面包屑导航路径
   */
  const breadcrumbs = computed(() => {
    const out: string[] = [];
    const l1 = level1Labels.value[activeTabIndex.value];
    if (l1) out.push(l1);
    const l2 = level2Labels.value[activeSecondIndex.value];
    if (l2 != null) out.push(l2);
    const baseEntry = gridBaseEntry.value;
    if (!baseEntry) return out;
    let cur: unknown = baseEntry.value;
    let curPath: DataPath = baseEntry.path;
    for (const idx of gridPath.value) {
      const step = computeGridEntries(cur, curPath);
      if (idx >= 0 && idx < step.labels.length) out.push(step.labels[idx]);
      const meta = step.metas[idx];
      if (!meta) break;
      cur = step.values[idx];
      curPath = meta.path;
    }
    return out;
  });

  /**
   * 面包屑 PrimeVue MenuItem 模型
   */
  const breadcrumbModel = computed(() =>
    breadcrumbs.value.map((label, idx) => ({
      label,
      ...(idx < breadcrumbs.value.length - 1 ? { command: () => navigateTo(idx) } : {}),
    })),
  );

  /**
   * 选择第一级标签
   */
  function selectLevel1(idx: number) {
    if (editMode.value) return;
    if (idx === activeTabIndex.value) return;
    activeTabIndex.value = idx;
    activeSecondIndex.value = 0;
    gridPath.value = [];
  }

  /**
   * 选择第二级标签
   */
  function selectLevel2(idx: number) {
    if (editMode.value) return;
    if (idx === activeSecondIndex.value) return;
    activeSecondIndex.value = idx;
    gridPath.value = [];
  }

  /**
   * 导航到指定层级
   */
  function navigateTo(idx: number) {
    if (editMode.value) return;
    if (idx < 0) {
      gridPath.value = [];
      return;
    }
    if (idx <= 1) {
      gridPath.value = [];
      return;
    }
    gridPath.value = gridPath.value.slice(0, idx - 2);
  }

  // watch 持久化（跳过初始化触发，避免覆盖待恢复的值）
  watch(
    [activeTabIndex, activeSecondIndex, gridPath],
    ([l1, l2, path]) => {
      try {
        const stored = localStorage.getItem('quicksend:lastSelection');
        const base = stored ? JSON.parse(stored) : {};
        localStorage.setItem(
          'quicksend:lastSelection',
          JSON.stringify({
            l1,
            l2,
            path: Array.isArray(path) ? [...path] : [],
            sel: base.sel ?? null,
          }),
        );
      } catch (e) {
        // ignore
      }
    },
  );

  // 边界检查
  watch(level1Labels, list => {
    if (activeTabIndex.value >= list.length) activeTabIndex.value = 0;
  });

  watch(level2Labels, list => {
    if (activeSecondIndex.value >= list.length) activeSecondIndex.value = 0;
  });

  return {
    // 状态（readonly）
    activeTabIndex,
    activeSecondIndex,
    gridPath,

    // computed
    level1Entries,
    level2Entries,
    gridBaseEntry,
    gridCurrent,
    breadcrumbs,
    breadcrumbModel,

    // 方法
    selectLevel1,
    selectLevel2,
    navigateTo,

    // 内部方法（供外部使用）
    computeGridEntries,
    restoreFromStorage,
  };
}
