import type { ExportFile, ExportData, PrefixSuffixItem } from '../types';

/** 文件大小限制：5MB */
const MAX_FILE_SIZE = 5 * 1024 * 1024;

/**
 * 读取用户选择的文件
 */
export function readImportFile(): Promise<File | null> {
  return new Promise(resolve => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';

    input.onchange = () => {
      const file = input.files?.[0];
      resolve(file ?? null);
    };

    input.oncancel = () => {
      resolve(null);
    };

    input.click();
  });
}

/**
 * 解析文件内容为 ExportFile 对象
 */
export function parseImportFile(file: File): Promise<ExportFile> {
  return new Promise((resolve, reject) => {
    if (file.size > MAX_FILE_SIZE) {
      reject(new Error('文件过大，请选择小于 5MB 的文件'));
      return;
    }

    const reader = new FileReader();

    reader.onload = () => {
      try {
        const content = reader.result as string;
        const parsed = JSON.parse(content);
        resolve(parsed);
      } catch (error) {
        reject(new Error('导入文件格式不正确，请检查文件内容'));
      }
    };

    reader.onerror = () => {
      reject(new Error('文件读取失败，请重试'));
    };

    reader.readAsText(file);
  });
}

/**
 * 校验导入文件格式
 */
export function validateImportFile(file: ExportFile): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  if (!file.data) {
    errors.push('缺少 data 字段');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * 校验数据类型
 */
export function validateExportData(data: ExportData): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  if (data.data !== undefined && !Array.isArray(data.data)) {
    errors.push('data 字段必须为数组');
  }

  if (data.prefix !== undefined && !isValidPrefixSuffixArray(data.prefix)) {
    errors.push('prefix 字段格式不正确');
  }

  if (data.suffix !== undefined && !isValidPrefixSuffixArray(data.suffix)) {
    errors.push('suffix 字段格式不正确');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * 校验前缀/后缀数组格式
 */
function isValidPrefixSuffixArray(arr: unknown): arr is PrefixSuffixItem[] {
  if (!Array.isArray(arr)) return false;

  return arr.every(item => {
    if (typeof item !== 'object' || item === null) return false;
    const keys = Object.keys(item);
    if (keys.length !== 1) return false;
    return typeof item[keys[0]] === 'string';
  });
}
