import { computed, type ComputedRef } from 'vue';
import type { RawData } from '../types';
import { persistRawData } from '../utils/persist';

/** 弹窗尺寸视图（与 ThemeSettingsModal 的 QuickSendPopupSize 等价） */
export interface QuickSendPopupSize {
  desktop: { width: string; height: string };
  mobile: { width: string; height: string };
}

/**
 * 快捷指令面板弹窗尺寸管理 composable
 * 接收 rawData 作为参数，提供 iframe 当前尺寸、设置弹窗模型视图与更新方法
 */
export function usePanelSize(rawData: RawData): {
  size: ComputedRef<{
    mobileHeight?: string;
    mobileWidth?: string;
    desktopHeight?: string;
    desktopWidth?: string;
  }>;
  popupSizeModel: ComputedRef<QuickSendPopupSize>;
  handlePopupSizeUpdate: (next: QuickSendPopupSize) => void;
} {
  const size = computed(() => ({
    mobileHeight: rawData.popupSize?.mobile?.height,
    mobileWidth: rawData.popupSize?.mobile?.width,
    desktopHeight: rawData.popupSize?.desktop?.height,
    desktopWidth: rawData.popupSize?.desktop?.width,
  }));

  /** 传给设置弹窗的尺寸视图：缺失字段回退默认值，保证子组件解析不出空字符串 */
  const popupSizeModel = computed<QuickSendPopupSize>(() => ({
    desktop: {
      width: rawData.popupSize?.desktop?.width ?? '50dvw',
      height: rawData.popupSize?.desktop?.height ?? '60dvh',
    },
    mobile: {
      width: rawData.popupSize?.mobile?.width ?? '90dvw',
      height: rawData.popupSize?.mobile?.height ?? '80dvh',
    },
  }));

  /** 设置弹窗写回新尺寸时，更新 rawData.popupSize 并持久化 */
  function handlePopupSizeUpdate(next: QuickSendPopupSize): void {
    rawData.popupSize = {
      desktop: { ...next.desktop },
      mobile: { ...next.mobile },
    };
    persistRawData(rawData);
  }

  return { size, popupSizeModel, handlePopupSizeUpdate };
}
