import { ref, computed, shallowRef } from 'vue';
import type { RawData, ExportSelection, ImportMode, ImportSelection, ExportFile } from '../types';
import {
  buildExportData,
  createExportFile,
  downloadJSON,
  formatExportPathKey,
  generateExportFilename,
} from '../utils/export-utils';
import { readImportFile, parseImportFile, validateImportFile, validateExportData } from '../utils/import-utils';
import { executeMerge } from '../utils/merge-strategies';

/** 树节点类型（用于 PrimeVue Tree 组件） */
interface TreeNode {
  key: string;
  label?: string;
  children?: TreeNode[];
  leaf?: boolean;
  path?: (string | number)[];
}

/**
 * 导入导出功能 Composable
 */
export function useImportExport(
  rawData: () => RawData,
  persistRawData: (data: RawData) => void,
  refreshData: () => void,
) {
  const modalVisible = ref(false);
  const activeTab = ref(0);

  const exportSelection = shallowRef<ExportSelection>({
    data: {
      selectedPaths: new Set<string>(),
    },
    prefix: true,
    suffix: true,
  });

  const importFile = ref<ExportFile | null>(null);
  const importMode = ref<ImportMode>('merge');
  const importSelection = ref<ImportSelection>({
    data: true,
    prefix: true,
    suffix: true,
  });

  const fileInfo = computed(() => {
    if (!importFile.value) {
      return { name: '', size: '', exportTime: '' };
    }

    const file = importFile.value;
    const dataSize = JSON.stringify(file.data).length;
    const sizeKB = (dataSize / 1024).toFixed(2);

    return {
      name: '导入文件',
      size: `${sizeKB} KB`,
      exportTime: file.exportTime ? new Date(file.exportTime).toLocaleString('zh-CN') : '未知',
    };
  });

  const hasData = computed(() => {
    return importFile.value?.data?.data !== undefined;
  });

  const hasPrefix = computed(() => {
    return importFile.value?.data?.prefix !== undefined;
  });

  const hasSuffix = computed(() => {
    return importFile.value?.data?.suffix !== undefined;
  });

  const dataTree = shallowRef<TreeNode[]>([]);

  function refreshDataTree() {
    dataTree.value = buildDataTree(rawData().data);
  }

  function openModal(tab = 0) {
    activeTab.value = tab;
    modalVisible.value = true;
    if (tab === 0) {
      refreshDataTree();
      initializeExportSelection();
    }
  }

  function closeModal() {
    modalVisible.value = false;
    resetImportState();
  }

  function initializeExportSelection() {
    updateSelectedPaths(getRootDataPaths());
  }

  function selectAll() {
    updateSelectedPaths(getRootDataPaths());
  }

  function deselectAll() {
    updateSelectedPaths(new Set());
  }

  function updateSelectedPaths(selectedPaths: Set<string>) {
    exportSelection.value = {
      ...exportSelection.value,
      data: {
        ...exportSelection.value.data,
        selectedPaths,
      },
    };
  }

  /**
   * 获取顶层数据路径
   */
  function getRootDataPaths(): Set<string> {
    return new Set(rawData().data.map((_, index) => formatExportPathKey([index])));
  }

  function executeExport() {
    try {
      const data = buildExportData(rawData(), exportSelection.value);
      const file = createExportFile(data);
      const filename = generateExportFilename();
      downloadJSON(file, filename);

      toastr.success(`文件已保存为 ${filename}`, '导出成功');

      closeModal();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : '未知错误', '导出失败');
    }
  }

  function handleFileValidation(validation: { valid: boolean; errors: string[] }): boolean {
    if (validation.valid) return true;

    toastr.error(validation.errors.join('; '), '文件格式错误');
    return false;
  }

  function initializeImportSelection(parsed: ExportFile) {
    importFile.value = parsed;
    importSelection.value = {
      data: parsed.data.data !== undefined,
      prefix: parsed.data.prefix !== undefined,
      suffix: parsed.data.suffix !== undefined,
    };
  }

  async function selectFile() {
    try {
      const file = await readImportFile();
      if (!file) return;

      const parsed = await parseImportFile(file);

      if (!handleFileValidation(validateImportFile(parsed))) return;

      const dataValidation = validateExportData(parsed.data);
      if (!dataValidation.valid) {
        toastr.error(dataValidation.errors.join('; '), '数据格式错误');
        return;
      }

      initializeImportSelection(parsed);
      toastr.success('请选择导入内容和模式', '文件加载成功');
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : '未知错误', '文件读取失败');
    }
  }

  async function executeImport() {
    if (!importFile.value) return;

    try {
      const current = rawData();
      const imported = importFile.value.data;

      const merged = executeMerge(current, imported, importMode.value, importSelection.value);

      persistRawData(merged);
      refreshData();

      toastr.success('数据已更新', '导入成功');

      closeModal();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : '未知错误', '导入失败');
    }
  }

  function resetImportState() {
    importFile.value = null;
    importMode.value = 'merge';
    importSelection.value = {
      data: true,
      prefix: true,
      suffix: true,
    };
  }

  function buildDataTree(data: unknown[]): TreeNode[] {
    return data.map((item, index) => buildTreeNode(item, [index], false));
  }

  /**
   * 构建可选中的导出树节点
   */
  function buildTreeNode(item: unknown, path: (string | number)[], eager = true): TreeNode {
    const singleEntry = getSingleObjectEntry(item);
    if (singleEntry) {
      return buildSingleObjectNode(singleEntry, path, eager);
    }

    const hasChildren = hasTreeChildren(item);
    const children = eager ? buildTreeChildren(item, path) : [];
    return {
      key: formatExportPathKey(path),
      label: createTreeLabel(item),
      path,
      children: children.length > 0 ? children : undefined,
      leaf: !hasChildren,
    };
  }

  /**
   * 构建单键对象节点
   */
  function buildSingleObjectNode(entry: [string, unknown], path: (string | number)[], eager = true): TreeNode {
    const [name, value] = entry;
    const childPath = [...path, name];
    const hasChildren = hasTreeChildren(value);
    const children = eager ? buildTreeChildren(value, childPath) : [];
    return {
      key: formatExportPathKey(path),
      label: name,
      path,
      children: children.length > 0 ? children : undefined,
      leaf: !hasChildren,
    };
  }

  /**
   * 构建 grid 或对象子节点
   */
  function buildTreeChildren(item: unknown, path: (string | number)[]): TreeNode[] {
    if (Array.isArray(item)) return buildArrayTreeChildren(item, path);
    if (isPlainObject(item)) return buildObjectTreeChildren(item, path);
    return [];
  }

  /**
   * 构建数组子节点
   */
  function buildArrayTreeChildren(item: unknown[], path: (string | number)[]): TreeNode[] {
    const grid = getGridChildren(item);
    const source = grid ? grid.children : item;
    const basePath = grid ? [...path, grid.index] : path;
    return source.map((child, index) => buildTreeNode(child, [...basePath, index], false));
  }

  /**
   * 构建对象子节点
   */
  function buildObjectTreeChildren(item: Record<string, unknown>, path: (string | number)[]): TreeNode[] {
    return Object.entries(item).map(([key, value]) => {
      return buildNamedTreeNode(key, value, [...path, key]);
    });
  }

  /**
   * 构建只显示名称的树节点
   */
  function buildNamedTreeNode(name: string, item: unknown, path: (string | number)[]): TreeNode {
    const hasChildren = hasTreeChildren(item);
    return {
      key: formatExportPathKey(path),
      label: name,
      path,
      leaf: !hasChildren,
    };
  }

  /**
   * 按需展开导出树节点
   */
  function expandDataNode(node: TreeNode) {
    if (node.children?.length || node.leaf || !node.path) return;

    const item = getValueByPath(rawData().data, node.path);
    const children = buildTreeChildrenForNode(item, node.path);
    if (children.length > 0) {
      dataTree.value = patchTreeChildren(dataTree.value, node.key, children);
      syncExpandedChildSelection(node.key, children);
    }
  }

  /**
   * 同步已选父节点的新子级选择
   */
  function syncExpandedChildSelection(parentKey: string, children: TreeNode[]) {
    const selectedPaths = exportSelection.value.data.selectedPaths;
    if (!selectedPaths.has(parentKey)) return;

    const next = new Set(selectedPaths);
    collectTreeKeys(children, next);
    updateSelectedPaths(next);
  }

  /**
   * 收集树节点键
   */
  function collectTreeKeys(nodes: TreeNode[], result: Set<string>) {
    nodes.forEach(node => {
      result.add(node.key);
      if (node.children?.length) collectTreeKeys(node.children, result);
    });
  }

  /**
   * 构建展开节点的子节点
   */
  function buildTreeChildrenForNode(item: unknown, path: (string | number)[]): TreeNode[] {
    const singleEntry = getSingleObjectEntry(item);
    if (!singleEntry) return buildTreeChildren(item, path);

    return buildTreeChildren(singleEntry[1], [...path, singleEntry[0]]);
  }

  /**
   * 替换树节点子级
   */
  function patchTreeChildren(nodes: TreeNode[], key: string, children: TreeNode[]): TreeNode[] {
    return nodes.map(node => {
      if (node.key === key) return { ...node, children, leaf: false };
      if (!node.children?.length) return node;
      return { ...node, children: patchTreeChildren(node.children, key, children) };
    });
  }

  /**
   * 生成树节点标签
   */
  function createTreeLabel(item: unknown): string {
    return extractItemLabel(item);
  }

  function extractItemLabel(item: unknown): string {
    if (typeof item === 'string') return item;
    if (typeof item === 'number') return String(item);
    if (typeof item === 'boolean') return String(item);
    if (item === null) return 'null';
    if (item === undefined) return 'undefined';

    if (Array.isArray(item)) {
      if (item.length === 0) return '[]';
      if (typeof item[0] === 'string') return item[0];
      return `数组 (${item.length} 项)`;
    }

    if (isPlainObject(item)) {
      const entries = Object.entries(item);
      if (entries.length === 0) return '{}';

      // 尝试找到有意义的字段
      const meaningfulKeys = ['name', 'title', 'label', 'text', 'id'];
      for (const key of meaningfulKeys) {
        if (key in item && typeof (item as Record<string, unknown>)[key] === 'string') {
          return String((item as Record<string, unknown>)[key]);
        }
      }

      // 显示第一个字段
      const [firstKey, firstValue] = entries[0];
      const valueStr =
        typeof firstValue === 'string'
          ? firstValue
          : typeof firstValue === 'number' || typeof firstValue === 'boolean'
            ? String(firstValue)
            : '...';
      return `${firstKey}: ${valueStr}`;
    }

    return String(item);
  }

  function isPlainObject(value: unknown): value is Record<string, unknown> {
    return (
      typeof value === 'object' &&
      value !== null &&
      !Array.isArray(value) &&
      Object.prototype.toString.call(value) === '[object Object]'
    );
  }

  /**
   * 读取单键对象条目
   */
  function getSingleObjectEntry(value: unknown): [string, unknown] | null {
    if (!isPlainObject(value)) return null;

    const entries = Object.entries(value);
    return entries.length === 1 ? entries[0] : null;
  }

  /**
   * 读取快捷指令 grid 子数组
   */
  function getGridChildren(value: unknown[]): { index: number; children: unknown[] } | null {
    if (Array.isArray(value[1])) return { index: 1, children: value[1] };
    return null;
  }

  /**
   * 判断节点是否可展开
   */
  function hasTreeChildren(value: unknown): boolean {
    if (Array.isArray(value)) {
      const grid = getGridChildren(value);
      return grid ? grid.children.length > 0 : value.length > 0;
    }
    return isPlainObject(value) && Object.keys(value).length > 0;
  }

  /**
   * 按路径读取导出树数据
   */
  function getValueByPath(root: unknown, path: (string | number)[]): unknown {
    return path.reduce<unknown>((current, segment) => {
      if (current == null) return undefined;
      return (current as Record<string | number, unknown>)[segment];
    }, root);
  }

  return {
    modalVisible,
    activeTab,
    exportSelection,
    importFile,
    importMode,
    importSelection,
    fileInfo,
    hasData,
    hasPrefix,
    hasSuffix,
    dataTree,
    openModal,
    closeModal,
    selectAll,
    deselectAll,
    expandDataNode,
    executeExport,
    selectFile,
    executeImport,
  };
}
