import { nextTick, onMounted, type ComputedRef, type Ref } from 'vue';
import type { DataPath, ItemEntry, LastSelection } from '../types';

interface UseQuickSendRestoreOptions {
  activeTabIndex: Ref<number>;
  activeSecondIndex: Ref<number>;
  gridPath: Ref<number[]>;
  selectedGridIndex: Ref<number | null>;
  level1Entries: ComputedRef<ItemEntry[]>;
  level2Entries: ComputedRef<ItemEntry[]>;
  gridBaseEntry: ComputedRef<ItemEntry | null>;
  restoreFromStorage: () => LastSelection;
  computeGridEntries: (node: unknown, basePath: DataPath) => {
    labels: string[];
    values: unknown[];
    metas: Array<{ path: DataPath }>;
  };
  onGridEntryClick: (idx: number, options?: { replace?: boolean }) => void;
  appendSillyTavernText: () => void;
}

/** 恢复快捷指令面板上次选择：L1/L2/Grid 路径与选中项 */
export function useQuickSendRestore(options: UseQuickSendRestoreOptions): void {
  onMounted(() => {
    const saved = options.restoreFromStorage();
    restoreTabs(options, saved);
    const restored = restoreGridPath(options, saved.path ?? []);
    restoreSelectedGrid(options, saved.sel, restored);
    // 恢复完成后立即获取 ST 输入框内容
    nextTick(() => {
      options.appendSillyTavernText();
    });
  });
}

/** 恢复 L1/L2 tab */
function restoreTabs(options: UseQuickSendRestoreOptions, saved: LastSelection): void {
  options.activeTabIndex.value = clampIndex(saved.l1, options.level1Entries.value.length);
  options.activeSecondIndex.value = clampIndex(saved.l2, options.level2Entries.value.length);
}

/** 夹取合法索引 */
function clampIndex(index: number, length: number): number {
  return length > 0 && index >= 0 && index < length ? index : 0;
}

/** 恢复 Grid 下钻路径 */
function restoreGridPath(options: UseQuickSendRestoreOptions, path: number[]): { labels: string[] } {
  const base = options.gridBaseEntry.value;
  if (!base) {
    options.gridPath.value = [];
    options.selectedGridIndex.value = null;
    return { labels: [] };
  }
  const restored = collectValidPath(options, base, path);
  options.gridPath.value = restored.path;
  return restored.current;
}

/** 收集仍然有效的 Grid 路径 */
function collectValidPath(options: UseQuickSendRestoreOptions, base: ItemEntry, path: number[]) {
  let currentNode: unknown = base.value;
  let currentPath = base.path;
  const restoredPath: number[] = [];
  for (const stepIdx of path) {
    const step = options.computeGridEntries(currentNode, currentPath);
    if (stepIdx < 0 || stepIdx >= step.labels.length) break;
    restoredPath.push(stepIdx);
    currentNode = step.values[stepIdx];
    currentPath = step.metas[stepIdx]?.path ?? currentPath;
  }
  return {
    path: restoredPath,
    current: options.computeGridEntries(currentNode, currentPath),
  };
}

/** 恢复 Grid 选中项 */
function restoreSelectedGrid(
  options: UseQuickSendRestoreOptions,
  savedSel: number | null,
  current: { labels: string[] },
): void {
  const nextIndex = getSelectedIndex(savedSel, current.labels.length);
  options.selectedGridIndex.value = nextIndex;
  if (nextIndex != null) nextTick(() => options.onGridEntryClick(nextIndex, { replace: true }));
}

/** 获取恢复用选中索引 */
function getSelectedIndex(savedSel: number | null, length: number): number | null {
  if (typeof savedSel === 'number' && savedSel >= 0 && savedSel < length) return savedSel;
  return length > 0 ? 0 : null;
}
